package com.ksenc.engineersdiary;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root; int blue=0xff174e98; interface Calc {String run(double[] v);} String fmt(double x){return String.format(Locale.US,"%,.3f",x);}
 public void onCreate(Bundle b){super.onCreate(b);home();}
 void page(String title){ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,36,24,24);root.setBackgroundColor(0xfff4f7fb);s.addView(root);setContentView(s);s.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(24,36+i.getSystemWindowInsetTop(),24,24+i.getSystemWindowInsetBottom());return i;});label(title,26);}
 void label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(blue);t.setPadding(0,12,0,12);root.addView(t);}
 void button(String s,Runnable r){Button b=new Button(this);b.setAllCaps(false);b.setText(s);root.addView(b);b.setOnClickListener(v->r.run());}
 void tool(String name,String[] fields,Calc c){page(name);button("Home",()->home());EditText[] e=new EditText[fields.length];for(int i=0;i<fields.length;i++){label(fields[i],14);e[i]=new EditText(this);e[i].setSingleLine();e[i].setInputType(8194);root.addView(e[i]);}TextView result=new TextView(this);result.setTextSize(20);result.setPadding(0,20,0,20);button("Calculate",()->{try{double[] a=new double[e.length];for(int i=0;i<a.length;i++){a[i]=Double.parseDouble(e[i].getText().toString());if(!Double.isFinite(a[i])||a[i]<0)throw new Exception();}result.setText(c.run(a));}catch(Exception ex){result.setText("Enter valid non-negative values.");}});root.addView(result);button("Save result",()->{if(result.getText().length()==0||result.getText().toString().startsWith("Enter"))return;SharedPreferences p=getSharedPreferences("diary",0);p.edit().putString("history",name+"\n"+result.getText()+"\n\n"+p.getString("history","")).apply();Toast.makeText(this,"Saved",0).show();});button("Share result",()->share(name+"\n"+result.getText()));label("Verify inputs, assumptions and results before professional use.",14);}
 void share(String text){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,text);startActivity(Intent.createChooser(i,"Share"));}
 void add(String n,String[] f,Calc c){button(n,()->tool(n,f,c));} String[] f(String... s){return s;}
 void home(){page("Engineers Diary");label(new java.text.SimpleDateFormat("EEEE, dd MMMM yyyy",Locale.getDefault()).format(new Date()),16);button("Daily Diary",()->records("Daily Diary"));button("Planner",()->records("Planner"));button("Tasks",()->records("Tasks"));button("Technical Notes",()->records("Technical Notes"));button("Engineering Tools",()->tools());}
 void tools(){page("Engineering Tools");button("Home",()->home());label("LAND & SURVEY",16);add("Rectangular land",f("Length (m)","Width (m)"),a->area(a[0]*a[1]));add("Triangular land",f("Base (m)","Height (m)"),a->area(a[0]*a[1]/2));add("Trapezoidal land",f("Parallel side A (m)","Parallel side B (m)","Perpendicular height (m)"),a->area((a[0]+a[1])*a[2]/2));add("Slope",f("Rise (m)","Horizontal run (m)"),a->{if(a[1]==0)throw new IllegalArgumentException();return fmt(100*a[0]/a[1])+" %\n"+fmt(Math.toDegrees(Math.atan(a[0]/a[1])))+" degrees";});label("BUILDING & CONSTRUCTION",16);add("Concrete / excavation volume",f("Length (m)","Width (m)","Depth (m)"),a->fmt(a[0]*a[1]*a[2])+" m³");add("Nominal concrete mix estimate",f("Wet volume (m³)","Cement ratio","Sand ratio","Aggregate ratio","Dry volume factor"),a->{double t=a[1]+a[2]+a[3];if(t==0||a[4]==0)throw new IllegalArgumentException();double d=a[0]*a[4]/t;return "Cement: "+fmt(d*a[1]*1440/50)+" bags (50 kg)\nSand: "+fmt(d*a[2])+" m³\nAggregate: "+fmt(d*a[3])+" m³\nAssumed cement bulk density 1440 kg/m³";});add("Steel weight",f("Diameter (mm)","Length per bar (m)","Number of bars"),a->fmt(Math.PI*Math.pow(a[0]/1000,2)/4*a[1]*a[2]*7850)+" kg (density 7850 kg/m³)");add("Brick / block count",f("Net wall area (m²)","Nominal unit length incl. joint (mm)","Nominal unit height incl. joint (mm)","Waste (%)"),a->{if(a[1]*a[2]==0)throw new IllegalArgumentException();return Math.ceil(a[0]*1e6/(a[1]*a[2])*(1+a[3]/100))+" units";});add("Plaster volume",f("Net area (m²)","Thickness (mm)"),a->fmt(a[0]*a[1]/1000)+" m³ wet mortar");add("Paint quantity",f("Net area (m²)","Coats","Coverage (m²/L per coat)"),a->{if(a[2]==0)throw new IllegalArgumentException();return fmt(a[0]*a[1]/a[2])+" L";});add("Floor tiles",f("Floor area (m²)","Tile length (mm)","Tile width (mm)","Waste (%)"),a->{if(a[1]*a[2]==0)throw new IllegalArgumentException();return Math.ceil(a[0]*1e6/(a[1]*a[2])*(1+a[3]/100))+" tiles";});add("Rectangular column formwork",f("Width (m)","Depth (m)","Height (m)","Number of columns"),a->fmt(2*(a[0]+a[1])*a[2]*a[3])+" m² (four sides)");label("UNIT CONVERSIONS",16);add("Area conversion",f("Area (m²)"),a->area(a[0]));add("Length conversion",f("Length (m)"),a->fmt(a[0]*3.280839895)+" ft\n"+fmt(a[0]*39.37007874)+" in\n"+fmt(a[0]*1000)+" mm");add("Volume conversion",f("Volume (m³)"),a->fmt(a[0]*35.3146667)+" ft³\n"+fmt(a[0]*1000)+" L");button("Saved calculations",()->{page("Saved calculations");button("Home",()->home());label(getSharedPreferences("diary",0).getString("history","No saved calculations"),16);button("Clear history",()->new AlertDialog.Builder(this).setMessage("Delete all saved calculations?").setPositiveButton("Delete",(d,w)->{getSharedPreferences("diary",0).edit().remove("history").apply();home();}).setNegativeButton("Cancel",null).show());});button("About & privacy",()->{page("About Engineers Diary");button("Home",()->home());label("KS Engineering & Construction\nadmin@ksenc.in\nOffline tools. No ads or accounts. Saved records stay on this device unless shared.",16);button("Privacy policy",()->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://ksstructurescbe.github.io/engineers-diary/privacy.html"))));});}
 void records(String kind){page(kind);button("Home",()->home());button("New entry",()->editRecord(kind,null));SharedPreferences p=getSharedPreferences("workspace",0);TreeMap<String,String> sorted=new TreeMap<>(Collections.reverseOrder());for(Map.Entry<String,?> e:p.getAll().entrySet())if(e.getKey().startsWith(kind+"|"))sorted.put(e.getKey(),String.valueOf(e.getValue()));for(Map.Entry<String,String> e:sorted.entrySet()){String key=e.getKey();String date=new java.text.SimpleDateFormat("dd MMM yyyy HH:mm",Locale.getDefault()).format(new Date(Long.parseLong(key.substring(key.indexOf('|')+1))));button(date+"\n"+e.getValue(),()->editRecord(kind,key));}if(sorted.isEmpty())label("No entries yet",16);}
 void editRecord(String kind,String key){page(kind);button("Back",()->records(kind));SharedPreferences p=getSharedPreferences("workspace",0);EditText input=new EditText(this);input.setMinLines(5);input.setGravity(Gravity.TOP);input.setHint(kind.equals("Planner")?"Appointment date, time and details":kind.equals("Tasks")?"Task and due date":"Write your entry");if(key!=null)input.setText(p.getString(key,""));root.addView(input);button("Save",()->{String value=input.getText().toString().trim();if(value.isEmpty())return;p.edit().putString(key==null?kind+"|"+System.currentTimeMillis():key,value).apply();records(kind);});if(key!=null){button("Share",()->share(input.getText().toString()));button("Delete",()->new AlertDialog.Builder(this).setMessage("Delete this entry?").setPositiveButton("Delete",(d,w)->{p.edit().remove(key).apply();records(kind);}).setNegativeButton("Cancel",null).show());}}
 String area(double x){return fmt(x)+" m²\n"+fmt(x*10.763910417)+" ft²\n"+fmt(x/40.468564224)+" cents\n"+fmt(x/4046.8564224)+" acres\n"+fmt(x/10000)+" hectares\n"+fmt(x*10.763910417/2400)+" grounds (2400 ft²)";} @Override public void onBackPressed(){home();}
}